 houseProxy(width,depth,lodge){const g=new T.Group(),walls=mesh(new T.BoxGeometry(width,5.8,depth),mat(lodge?'#d5cfb9':'#c5bc9d'),g);walls.position.y=2.9;const timber=mesh(new T.BoxGeometry(width+.1,2.8,depth+.1),mat('#71513b'),g);timber.position.y=4.2;const h=width*.36,roof=mesh(new T.ConeGeometry(1,1,4),mat('#545551'),g);roof.scale.set((width+2)*.72,h,(depth+2)*.72);roof.rotation.y=Math.PI/4;roof.position.y=5.8+h/2;return g;}
 addTownDetails(town,y){const [x,z]=town.point;const bench=mesh(new T.BoxGeometry(3.1,.22,.65),mat('#80694c'),this.scene);bench.position.set(x+6,y+.55,z+8);for(const dx of[-1,1]){const leg=mesh(new T.BoxGeometry(.19,.6,.48),mat('#786b54'),this.scene);leg.position.set(x+6+dx,y+.2,z+8);}const basin=mesh(new T.CylinderGeometry(1.6,1.8,.7,20,1,true),mat('#8b9189',{side:T.DoubleSide}),this.scene);basin.position.set(x-5,y+.3,z+4);this.colliders.push({x:x-5,z:z+4,angle:0,hx:1.65,hz:1.65,y,top:y+.85});const water=mesh(new T.CircleGeometry(1.45,30),this.waterMaterial(),this.scene);water.rotation.x=-Math.PI/2;water.position.set(x-5,y+.4,z+4);
  const c=document.createElement('canvas');c.width=512;c.height=128;const ctx=c.getContext('2d');ctx.fillStyle='#5c4936';ctx.fillRect(0,0,512,128);ctx.fillStyle='#f1e9ca';ctx.textAlign='center';ctx.font='44px serif';ctx.fillText(town.name,256,78);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;const sign=mesh(new T.PlaneGeometry(3.4,.85),new T.MeshStandardMaterial({map:t,side:T.DoubleSide,roughness:.9}),this.scene);sign.position.set(x+9,y+2,z-10);const post=mesh(new T.CylinderGeometry(.08,.1,2.8,8),mat('#71523b'),this.scene);post.position.set(x+9,y+1.2,z-10);town.rest={x:x+6,z:z+8};}
